INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHD','بہرحال','بہرحال','word','baharhaal','anyway; in any case','A conversational connector meaning anyway or in any case. Common in speech and writing; it can move the conversation on or sum up despite what was just said.','بہرحال، ہمیں جانا ہے۔',NULL,'[]',0,0,'2026-09-11T00:00:00.000Z','2026-09-18','2026-09-18','airtable','rec2TURdxi2FVi5Oy','2026-09-18T00:38:47.775Z','2026-09-18T18:45:00.825Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHE','یوں ہی','یوں ہی','phrase','yoon hi','just like that; for no particular reason','Often means just like that, casually, or without any particular reason or purpose. Context can also give the sense of simply/in this way.','میں یوں ہی پوچھ رہا تھا۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-11','2026-10-06','airtable','rec4ep2TIahaz7Pgn','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHF','حیران','حیران','word','hairaan','surprised; amazed','Surprised, amazed, or astonished. Common construction: سن کر حیران ہونا, to be surprised on hearing something.','میں یہ سن کر حیران ہو گیا۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-08','2026-10-03','airtable','rec6Wu5A8k4aLskrp','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHG','جادو','جادو','word','jaadu','magic','Magic; supernatural or figuratively something that seems amazingly effective or impressive.','یہ تو جادو لگ رہا ہے۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-08','2026-10-03','airtable','rec7w6yX6vnaStx8C','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHH','الٹ','الٹ','word','ulat','opposite; reverse','The opposite or reverse of something. Also used literally for something turned over or upside down.','یہ اس کے بالکل الٹ ہے۔',NULL,'[]',0,2,'2026-09-08T00:00:00.000Z','2026-09-18','2026-09-23','airtable','rec82TpUgEoS5Rg0g','2026-09-18T00:38:47.775Z','2026-09-18T18:34:39.456Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHJ','در حقیقت','در حقیقت','phrase','dar-haqiqat','in fact; actually','Means in fact or actually, often used to clarify the real situation. More formal than casual اصل میں.','در حقیقت مسئلہ کچھ اور تھا۔',NULL,'[]',0,2,'2026-09-08T00:00:00.000Z','2026-09-18','2026-09-23','airtable','rec9robN2KNz6UY6N','2026-09-18T00:38:47.775Z','2026-09-18T18:34:47.619Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHK','قصداً','قصدا','word','qasdan','deliberately; on purpose','Means deliberately or on purpose. Somewhat formal; in ordinary Pakistani conversation جان بوجھ کر is usually more natural.','میں نے یہ قصداً نہیں کیا۔',NULL,'[]',0,2,'2026-09-11T00:00:00.000Z','2026-09-18','2026-09-23','airtable','recAPaL0WoleJw9y0','2026-09-18T00:38:47.775Z','2026-09-18T18:38:20.739Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHM','خصوصاً','خصوصا','word','khusoosan','especially; particularly','Means especially or particularly. Common but a little more formal than خاص طور پر.','مجھے یہ جگہ خصوصاً سردیوں میں پسند ہے۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-11','2026-10-06','airtable','recBgc3FvFzc5Z182','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHN','اچانک','اچانک','word','achaanak','suddenly; unexpectedly','Something happening suddenly or unexpectedly. Very common in everyday Urdu.','اچانک بارش شروع ہو گئی۔',NULL,'[]',0,5,'2026-09-08T00:00:00.000Z','2026-09-11','2028-05-28','airtable','recCqK9fTDL3DoLDz','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHP','لفظ','لفظ','word','lafz','word','A word. The common plural is الفاظ (alfaaz).','مجھے یہ لفظ یاد نہیں آ رہا۔',NULL,'[]',0,5,'2026-09-08T00:00:00.000Z','2026-09-08','2028-05-25','airtable','recEnSwlvOHBNEZQB','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHQ','اتفاقاً','اتفاقا','word','ittifaaqan','coincidentally; by chance','Something happening by coincidence or chance. More polished than casually saying اتفاق سے.','اتفاقاً وہ بھی وہیں موجود تھا۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-11','2026-10-06','airtable','recFBIIHP63egmdZi','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHR','ویسے بھی','ویسے بھی','phrase','waise bhi','anyway; besides; in any case','A very common conversational phrase meaning anyway, besides, or in any case, often adding another reason.','میں ویسے بھی آج گھر پر رہنے والا تھا۔',NULL,'[]',0,4,'2026-09-08T00:00:00.000Z','2026-09-14','2027-01-17','airtable','recGqsjD5hX2cZhCX','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHS','عملاً','عملا','word','amalan','in practice; practically','Means in practice or practically, often contrasting what happens in reality with theory or official claims. Somewhat formal.','یہ منصوبہ عملاً ختم ہو چکا ہے۔',NULL,'[]',0,1,'2026-09-08T00:00:00.000Z','2026-09-18','2026-09-19','airtable','recHdk7LF4hGoOuIp','2026-09-18T00:38:47.775Z','2026-09-18T18:43:29.787Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHT','حالانکہ','حالانکہ','word','halaanke','although; even though','Introduces a contrast: although, even though. Common in both speech and writing.','حالانکہ بارش ہو رہی تھی، ہم باہر گئے۔',NULL,'[]',0,0,'2026-09-08T00:00:00.000Z','2026-09-18','2026-09-18','airtable','recMikfZK8L8wxN75','2026-09-18T00:38:47.775Z','2026-09-18T18:44:42.982Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHV','ٹھنڈ','ٹھنڈ','word','thand','cold; cold weather','Everyday noun for cold or cold weather. Common in expressions like ٹھنڈ لگنا (to feel cold) and ٹھنڈ پڑنا (for the weather to turn cold).','آج کافی ٹھنڈ ہے۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-09','2026-10-04','airtable','recNTXVFE4oS4SRcP','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHW','ایک دم','ایک دم','phrase','aik dam','suddenly; all at once; completely','Very common spoken phrase. Depending on context it can mean suddenly/all at once, or completely/absolutely.','ایک دم بجلی چلی گئی۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-17','2026-10-12','airtable','recNzASTAi5eK6bnt','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHX','فطری','فطری','word','fitri','natural; instinctive','Natural, innate, or instinctive; something arising naturally rather than being artificial or forced.','یہ ردِعمل بالکل فطری ہے۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-11','2026-10-06','airtable','recPuoyzQ2Y5v2wia','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHY','ذکر','ذکر','word','zikr','mention; reference','A mention or reference to someone or something. Common construction: کسی کا ذکر کرنا, to mention someone/something.','اس نے کل تمہارا ذکر کیا تھا۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-11','2026-10-06','airtable','recSvKvyFSOfoeeic','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBHZ','رسمی انداز','رسمی انداز','phrase','rasmi andaaz','formal style; formal manner','A formal style, manner, or way of speaking/behaving. Used when something is expressed in a more official, polished, or non-casual way.','وہ رسمی انداز میں بات کر رہا تھا۔',NULL,'["noun-abstract"]',0,4,'2026-09-08T00:00:00.000Z','2026-09-14','2027-01-17','airtable','recU9BvFGfoJY5Oqj','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ0','مشق','مشق','word','mashq','practice; exercise','Practice or an exercise done to improve a skill, including language practice.','روز تھوڑی سی مشق کرو۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-17','2026-10-12','airtable','recVpJTS1YKj061pY','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ1','مہارت','مہارت','word','maharat','skill; proficiency','A skill or proficiency, especially something learned or developed through practice. In everyday Pakistani Urdu, English “skill” is also very common.','میں نے آج ایک نئی مہارت سیکھی۔',NULL,'[]',0,2,'2026-09-14T00:00:00.000Z','2026-09-18','2026-09-23','airtable','recWaCmNwzi9NhpkO','2026-09-18T00:38:47.775Z','2026-09-18T18:38:39.796Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ2','غیر رسمی انداز','غیر رسمی انداز','phrase','ghair rasmi andaaz','informal style; casual manner','An informal or casual way of speaking, writing, or behaving; the opposite of رسمی انداز.','دوستوں سے میں غیر رسمی انداز میں بات کرتا ہوں۔',NULL,'[]',0,4,'2026-09-08T00:00:00.000Z','2026-09-14','2027-01-17','airtable','recYubONx5N6cdTmL','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ3','لباس','لباس','word','libaas','clothing; dress; attire','A general word for clothing, dress, or attire. More formal or general than everyday کپڑے.','اس کا لباس بہت سادہ ہے۔',NULL,'[]',0,3,'2026-09-11T00:00:00.000Z','2026-09-18','2026-10-13','airtable','recbZqjeyofsBwEWu','2026-09-18T00:38:47.775Z','2026-09-18T18:38:30.368Z');
