INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ6','خوشگوار','خوشگوار','word','khushgawaar','pleasant; agreeable','Pleasant, agreeable, or enjoyable, often describing weather, atmosphere, experiences, or feelings.','آج موسم بہت خوشگوار ہے۔',NULL,'[]',0,4,'2026-09-08T00:00:00.000Z','2026-09-11','2027-01-14','airtable','rech5jAMk5Cpl65LQ','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJ7','تقریباً','تقریبا','word','taqreeban','approximately; about; almost','Used for approximate amounts, times, or numbers; can also mean almost depending on context.','ہم تقریباً پانچ بجے پہنچے۔',NULL,'[]',0,3,'2026-09-08T00:00:00.000Z','2026-09-17','2026-10-12','airtable','rechs3Qys61ETy0gI','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
