INSERT INTO "vocab" ("id","urdu","urdu_key","kind","roman","english","notes","example_urdu","example_english","tags","favourite","mastery","added_at","last_reviewed_on","next_review_on","source","airtable_id","created_at","updated_at") VALUES('01M2RZ776ZZDTCRT1FZDD6VBJA','عام طور پر','عام طور پر','phrase','aam taur par','usually; generally','Usually; generally; as a rule. A very common everyday Urdu phrase for something that normally or typically happens.','میں عام طور پر صبح چائے پیتا ہوں۔',NULL,'[]',0,4,'2026-09-08T00:00:00.000Z','2026-09-14','2027-01-17','airtable','recjHU59nOURh4wdo','2026-09-18T00:38:47.775Z','2026-09-18T00:38:47.775Z');
